-- 1.7M FCC radio and wireless licenses -- call sign, licensee, status, grant and expiry dates.
-- Auto-generated by scripts/gen_evidence_pages.py: 1,689,338 rows > 100k, so this is a BOUNDED pre-aggregate (parquet-safe by construction), not select *.
select year("GRANT_DATE") as year, count(*) as records
from THE_LIBRARY.GOVERNMENT.FCC_RADIO_LICENSES
where "GRANT_DATE" is not null
group by 1
order by 1
